 useEffect(()=>{if(allState&&activePage!=='all'&&!allState.pages.some(p=>p.id===activePage))choosePage(allState.pages[0]?.id||'all');},[allState?.pages.length]);
 const refresh=async()=>{let next;try{next=await request('/api/state');}catch(e){if(e.status>=500){setWorkerIssue(e.message);if(!allState)throw e;return;}throw e;}setWorkerIssue(null);setState(next);if(next.actor.role==='super_admin')setOwner(await request('/api/owner/state'));};
 useEffect(()=>{if(!workerIssue||allState)return;const id=setInterval(()=>refresh().catch(()=>{}),8000);return()=>clearInterval(id);},[!!workerIssue,!!allState]);
 useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(null),8000);return()=>clearTimeout(id);},[notice]);
 useEffect(()=>{request('/api/public').then(setPublic).catch(e=>setError(e.message));refresh().catch(e=>{if(!e.message.includes('Sign in'))setError(e.message);}).finally(()=>setLoading(false));},[]);
 useEffect(()=>{if(!state||loggedOut)return;const id=setInterval(()=>refresh().catch(e=>setError(e.message)),5000);return()=>clearInterval(id);},[!!state,loggedOut]);
 useEffect(()=>{if(!allState)return;if((view==='feeds'&&selectedPage?.kind!=='news')||(view==='products'&&selectedPage?.kind!=='ecommerce'))setView('overview');if(!selectedPage&&['feeds','products','connections','settings','websites','automations','studio','insights'].includes(view))setView('pages');},[activePage,view,!!allState]);
 const run=async(fn,{close=false}={})=>{if(busy)return;setBusy(true);setError(null);setNotice(null);try{const result=await fn();if(close)setModal(null);if(result?.checks)setModal({kind:'result',title:'Dry-run checks',result});else if(result?.message)setNotice(result.message);else setNotice(result?.kind?'Task queued. Follow its progress below.':'Saved.');await refresh();}catch(e){setError(e.message);}finally{setBusy(false);}};
