 const tasks=state?.tasks?.filter(t=>t.status==='running'||t.status==='queued'&&new Date(t.not_before)<=new Date(Date.now()+5000))||[];
 if(loading)return <main className="startup"><div className="brandmark">E</div><p>Restoring your workspace…</p></main>;
 if(workerIssue&&!state&&!loggedOut)return <OfflineScreen retry={()=>refresh().catch(()=>{})}/>;
 if(!state||loggedOut)return <AuthScreen info={publicInfo} error={error} done={async()=>{setLoggedOut(false);setLoading(true);try{await refresh();}catch(e){setError(e.message);}finally{setLoading(false);}}}/>;
