 {['posts','review','drafts','scheduled','published','ready_manual','archive','trash'].includes(view)&&<div className="tabs content-tabs">{[['posts','All'],['drafts','Drafts'],['review',selectedPage&&!selectedPage.require_review?'Preparing / waiting':'Needs approval'],['scheduled','Scheduled'],...(selectedPage?.destination_type==='facebook_profile'?[['ready_manual','Ready to share']]:[]),['published','Published'],['archive','Archive'],['trash','Trash']].map(([id,label])=><button className={view===id?'active':''} key={id} onClick={()=>setView(id)}>{label} {['drafts','review','scheduled','published','ready_manual'].includes(id)?'('+count(id==='drafts'?'draft':id)+')':''}</button>)}</div>}
