 {view==='billing'&&<><div className="banner"><div><strong>{state.entitlements.plan_name}</strong>{state.entitlements.provider_customer&&<button onClick={()=>run(async()=>{const r=await request('/api/billing/portal',{});location.assign(r.url);})}>Manage card subscription</button>}<p>{state.entitlements.posts_used} of {state.entitlements.post_limit} publications reserved or used. Period ends {date(state.entitlements.period_end)}. The free trial is one initial seven-day period.</p></div></div><div className="cards plans">{state.plans.filter(p=>p.enabled).map(p=><article className="panel" key={p.id}><h2>{p.name}</h2><strong className="price">{p.id==='free'?'Free':money(p.usd_minor)}</strong><p className="muted">{p.period_days} days · {p.page_limit} Pages · {p.post_limit} posts</p><p>{p.generation_limit} caption / creative tasks</p>{p.id!=='free'&&<button className="primary" onClick={()=>open('payment',{plan_id:p.id})}>Choose payment method</button>}</article>)}</div><section className="panel"><h2>Payment history</h2>{state.payments.length?state.payments.map(p=><div className="line" key={p.id}><span>{words(p.method)} · {money(p.amount_minor,p.currency)}</span><Status value={p.status}/></div>):<p className="muted">No payment requests yet. Manual transfers activate a plan only after owner verification.</p>}</section></>}
 {view==='activity'&&<><WorkerTerminal key={activePage} state={state}/>{state.mirrorStatus?.length>0&&<section className="panel"><h2>Logging delivery</h2>{state.mirrorStatus.map(m=><div className="line" key={m.post_id+m.connection_id}><span>{state.connections.find(c=>c.id===m.connection_id)?.name}<small>{m.last_error||'Waiting to sync'}</small></span><Status value={m.status}/></div>)}</section>}<TaskList tasks={state.tasks}/><section className="panel"><h2>Workspace activity</h2>{state.activity.map(a=><div className="line" key={a.id}><span>{words(a.action.replaceAll('.',' '))}</span><small className="muted">{date(a.created_at)}</small></div>)}</section></>}
